window.products.push({"id":1021322,"name":"Hario Round Tea Pot, 290ml, Clear","category":"homeandappliances","retail price":27.6,"sale price":null,"image":"https://m.media-amazon.com/images/I/51G+2OGn8tL._AC_SL1000_.jpg","description":"This small tea pot is ideal for one person to make any type of loose leaf tea, herbal infusion or fruit tea. It has a removable strainer in the spout to keep the leaves in the pot as you pour yourself a wonderful cuppa. Great for any type of tea but recommended to serve in smaller cups only, due to tiny 180ml Asian teapot capacity. .","images":["https://m.media-amazon.com/images/I/51G+2OGn8tL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Hario","source_asin":"B002LW0HVM","category_path":"Home & Kitchen"},"sku":"BM-1021322","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B002LW0HVM","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B002LW0HVM","price_pending":true,"merchant_ready":false});
